-- Custom-group photos only; existing groups, membership and LINE bindings are unchanged.
create table private.custom_chat_group_photos(group_id uuid primary key references public.communication_groups(id) on delete cascade, storage_path text not null, updated_by uuid not null references auth.users(id), updated_at timestamptz not null default now());
alter table private.custom_chat_group_photos enable row level security;
revoke all on private.custom_chat_group_photos from public,anon,authenticated;
create function private.can_edit_custom_chat_photo(p_group_id uuid) returns boolean language sql stable security definer set search_path='' as $$ select auth.uid() is not null and private.can_access_communication_group(p_group_id) and exists(select 1 from public.communication_groups g where g.id=p_group_id and g.group_type='company' and g.participants_only and (g.created_by=auth.uid() or private.can_manage_communication_group(g.id))) $$;
create function private.custom_chat_group_photo_workspace() returns jsonb language sql stable security definer set search_path='' as $$ select coalesce(jsonb_agg(jsonb_build_object('group_id',g.id,'storage_path',p.storage_path,'can_edit',private.can_edit_custom_chat_photo(g.id))),'[]'::jsonb) from public.communication_groups g left join private.custom_chat_group_photos p on p.group_id=g.id where auth.uid() is not null and g.group_type='company' and g.participants_only and private.can_access_communication_group(g.id) $$;
create function private.set_custom_chat_group_photo(p_group_id uuid,p_storage_path text) returns void language plpgsql security definer set search_path='' as $$ begin
 if not private.can_edit_custom_chat_photo(p_group_id) then raise exception 'group photo permission required' using errcode='42501'; end if;
 if p_storage_path is null or p_storage_path not like p_group_id::text||'/'||auth.uid()::text||'/%' or p_storage_path like '%..%' or not exists(select 1 from storage.objects where bucket_id='custom-chat-photos' and name=p_storage_path and owner_id=auth.uid()::text) then raise exception 'uploaded group photo required'; end if;
 insert into private.custom_chat_group_photos(group_id,storage_path,updated_by) values(p_group_id,p_storage_path,auth.uid()) on conflict(group_id) do update set storage_path=excluded.storage_path,updated_by=excluded.updated_by,updated_at=now();
 end $$;
create function public.custom_chat_group_photo_workspace() returns jsonb language sql stable security invoker set search_path='' as $$ select private.custom_chat_group_photo_workspace() $$;
create function public.set_custom_chat_group_photo(p_group_id uuid,p_storage_path text) returns void language sql security invoker set search_path='' as $$ select private.set_custom_chat_group_photo(p_group_id,p_storage_path) $$;
revoke all on function private.can_edit_custom_chat_photo(uuid),private.custom_chat_group_photo_workspace(),private.set_custom_chat_group_photo(uuid,text),public.custom_chat_group_photo_workspace(),public.set_custom_chat_group_photo(uuid,text) from public,anon;
grant usage on schema private to authenticated;
grant execute on function private.can_edit_custom_chat_photo(uuid),private.custom_chat_group_photo_workspace(),private.set_custom_chat_group_photo(uuid,text),public.custom_chat_group_photo_workspace(),public.set_custom_chat_group_photo(uuid,text) to authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('custom-chat-photos','custom-chat-photos',false,5242880,array['image/jpeg','image/png']) on conflict(id) do nothing;
create policy custom_chat_photo_read on storage.objects for select to authenticated using(bucket_id='custom-chat-photos' and exists(select 1 from public.communication_groups g where g.id::text=split_part(name,'/',1) and private.can_access_communication_group(g.id)));
create policy custom_chat_photo_insert on storage.objects for insert to authenticated with check(bucket_id='custom-chat-photos' and split_part(name,'/',2)=auth.uid()::text and exists(select 1 from public.communication_groups g where g.id::text=split_part(name,'/',1) and private.can_edit_custom_chat_photo(g.id)));
-- Existing broad storage policies must never widen access to this new bucket.
create policy custom_chat_photo_read_boundary on storage.objects as restrictive for select to authenticated using(bucket_id<>'custom-chat-photos' or exists(select 1 from public.communication_groups g where g.id::text=split_part(name,'/',1) and private.can_access_communication_group(g.id)));
create policy custom_chat_photo_insert_boundary on storage.objects as restrictive for insert to authenticated with check(bucket_id<>'custom-chat-photos' or (split_part(name,'/',2)=auth.uid()::text and exists(select 1 from public.communication_groups g where g.id::text=split_part(name,'/',1) and private.can_edit_custom_chat_photo(g.id))));
create policy custom_chat_photo_no_update on storage.objects as restrictive for update to authenticated using(bucket_id<>'custom-chat-photos') with check(bucket_id<>'custom-chat-photos');
create policy custom_chat_photo_no_delete on storage.objects as restrictive for delete to authenticated using(bucket_id<>'custom-chat-photos');
create policy custom_chat_photo_no_anon on storage.objects as restrictive for all to anon using(bucket_id<>'custom-chat-photos') with check(bucket_id<>'custom-chat-photos');
